"""Small, self-contained AI lessons in the shared 90-day syllabus order.

The examples are invented teaching examples, not measured product results.
No model, account data, network access, or external reading is needed to use them.
"""
from __future__ import annotations

from copy import deepcopy


def _entry(title, idea, example, steps, task, answer, words):
    return dict(title=title, idea=idea, example=example, steps=list(steps),
                task=task, answer=answer, words=words)


